head.script:
scwin.gBzProcsNo;
scwin.gListStatCd;

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function() {
    try {
        $c.cm.PanelToGroupBox(panel_Top);
        const vCurDate = $c.ut.cGetToday("yyyymmdd");
        edt_SDate.setValue($c.ut.cGetMinusDate2(vCurDate, 14)); // 일주일전 날짜
        edt_EDate.setValue($c.ut.cGetToday("yyyymmdd")); // 현재날짜

        $c.stf.comboCbDataSetPeriod(cmb_PeriodTp);
        if (js_market === "1" || js_market === "2" || js_market === "6") {
            $c.cm.setColumnProp(grd_List, "TR_MKT_NM", "Show", false);
            panel_mkt_gubun.hide();
        } else {
            panel_mkt_gubun.show("");
        }
        await scwin.listSync();
        $c.cm.fn_com_isur(txb_ISUR_CD, txb_COM_NM);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF21501.onpageload" });
    }
};

/**
 * @method
 * @name onpageunload
 * @description 화면 언로드 시 정리 처리
 * @returns {void}
 * @hidden N
 */
scwin.onpageunload = function() {
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name img_COM_NM_onclick
 * @description img_COM_NM 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.img_COM_NM_onclick = function() {
    try {
        $c.cm.IsurcdSearch(txb_ISUR_CD, txb_COM_NM);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF21501.img_COM_NM_onclick" });
    }
};

/**
 * @method
 * @name btn_Search_onclick
 * @description 「조회」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_Search_onclick = async function() {
    try {
        if ($c.stf.compareFromToDate2(edt_SDate, edt_EDate)) {
            await scwin.listSync();
        }
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF21501.btn_Search_onclick" });
    }
};

/**
 * @method
 * @name btn_Excel_onclick
 * @description 「엑셀다운로드」 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.btn_Excel_onclick = function() {
    try {
        $c.stf.doLogSave("ULDSTF21501.xml", SCREN_PROCS_TP_CD_07); // 엑셀
        $c.data.downloadGridViewExcel(grd_List, {fileName: "자사주매매 내역", type: "8"});
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF21501.btn_Excel_onclick" });
    }
};

/**
 * @method
 * @name MxDataSet_com_isur_OnFilter
 * @description Mx Data Set com isur On Filter 처리
 * @param {Number} row 행 인덱스
 * @returns {void}
 * @hidden N
 */
scwin.MxDataSet_com_isur_OnFilter = function(row) {
    try {
        if (skw !== "" && foColum === "1") {
            f1 = MxDataSet_com_isur.getCellData(row, "COM_ABBRV");
            f2 = MxDataSet_com_isur.getCellData(row, "OLD_COM_ABBRV");
            if (f1.indexOf(skw) !== -1 || f2.indexOf(skw) !== -1) return true;

            else return false;
        } else return true;
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF21501.MxDataSet_com_isur_OnFilter" });
    }
};

/**
 * @method
 * @name txb_ISUR_CD_onkeyup
 * @description txb_ISUR_CD 키 입력 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.txb_ISUR_CD_onkeyup = function() {
    try {
        if (txb_ISUR_CD.getValue() === "") {
            Grd_com_isur.style.display = "none";
        } else {
            if (window.event.keyCode === 40) {
                // 아래화살표눌렀을때 그리드로 포커스
                Grd_com_isur.focus();
            } else {
                $c.cm.fn_com_isur_nm(window.event.keyCode);
            }
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF21501.txb_ISUR_CD_onkeyup" });
    }
};

/**
 * @method
 * @name txb_ISUR_CD_onfocus
 * @description txb_ISUR_CD 포커스 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.txb_ISUR_CD_onfocus = function() {
    try {
        Grd_com_isur.style.display = "none";
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF21501.txb_ISUR_CD_onfocus" });
    }
};

/**
 * @method
 * @name txb_ISUR_CD_onblur
 * @description txb_ISUR_CD 포커스 이탈 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.txb_ISUR_CD_onblur = function() {
    try {
        if (stFocusGrid === false) {
            Grd_com_isur.style.display = "none";
        }
        if (txb_ISUR_CD.getValue() === "") {
            txb_COM_NM.setValue("");
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF21501.txb_ISUR_CD_onblur" });
    }
};

/**
 * @method
 * @name Grd_com_isur_OnKeyPress
 * @description Grd com isur On Key Press 처리
 * @param {*} kcode kcode
 * @returns {void}
 * @hidden N
 */
scwin.Grd_com_isur_OnKeyPress = function(kcode) {
    try {
        if (kcode === '13') {
            $c.cm.fn_com_Confirm_set();
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF21501.Grd_com_isur_OnKeyPress" });
    }
};

/**
 * @method
 * @name Grd_com_isur_OnDblClick
 * @description Grd_com_isur 더블클릭 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} row 행 인덱스
 * @param {*} colid colid
 * @returns {void}
 * @hidden N
 */
scwin.Grd_com_isur_OnDblClick = function(row, colid) {
    try {
        $c.cm.fn_com_Confirm_set();
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF21501.Grd_com_isur_OnDblClick" });
    }
};

/**
 * @method
 * @name Grd_com_isur_OnClick
 * @description Grd_com_isur 클릭 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} row 행 인덱스
 * @param {*} colid colid
 * @returns {void}
 * @hidden N
 */
scwin.Grd_com_isur_OnClick = function(row, colid) {
    try {
        Grd_com_isur.style.display = "";
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF21501.Grd_com_isur_OnClick" });
    }
};

/**
 * @method
 * @name Grd_com_isur_OnSetFocus
 * @description Grd com isur On Set Focus 처리
 * @returns {void}
 * @hidden N
 */
scwin.Grd_com_isur_OnSetFocus = function() {
    try {
        stFocusGrid = true;
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF21501.Grd_com_isur_OnSetFocus" });
    }
};

/**
 * @method
 * @name Grd_com_isur_OnKillFocus
 * @description Grd_com_isur 포커스 이탈 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @returns {void}
 * @hidden N
 */
scwin.Grd_com_isur_OnKillFocus = function() {
    try {
        stFocusGrid = false;
        Grd_com_isur.style.display = "none";
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF21501.Grd_com_isur_OnKillFocus" });
    }
};

/**
 * @method
 * @name dts_List_OnLoadError
 * @description dts_List 로드 오류 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dts_List_OnLoadError = async function() {
    try {
        await $c.win.alert(dts_List);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF21501.dts_List_OnLoadError" });
    }
};

/**
 * @method
 * @name dts_List_OnLoadCompleted
 * @description dts_List 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} rowcount 조회 건수
 * @returns {void}
 * @hidden N
 */
scwin.dts_List_OnLoadCompleted = function(rowcount) {
    try {
        $c.stf.fillGridHeaderTotalCnt(rowcount, panel_page);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF21501.dts_List_OnLoadCompleted" });
    }
};

/**
 * @method
 * @name btn_Close_onclick
 * @description 「닫기」 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.btn_Close_onclick = function() {
    try {
        self.close();
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF21501.btn_Close_onclick" });
    }
};

/**
 * @method
 * @name btn_EDate_onclick
 * @description btn_EDate 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.btn_EDate_onclick = function() {
    try {
        popUpCalendar2(edt_EDate);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF21501.btn_EDate_onclick" });
    }
};

/**
 * @method
 * @name btn_SDate_onclick
 * @description btn_SDate 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.btn_SDate_onclick = function() {
    try {
        popUpCalendar2(edt_SDate);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF21501.btn_SDate_onclick" });
    }
};

/**
 * @method
 * @name cmb_PeriodTp_onselchange
 * @description cmb_PeriodTp onselchange 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.cmb_PeriodTp_onselchange = function() {
    try {
        const vTp = $c.cp.valueOfIndex(cmb_PeriodTp, "VALUE", cmb_PeriodTp.getSelectedIndex());
        $c.stf.setFromToDate(vTp, edt_SDate, edt_EDate);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF21501.cmb_PeriodTp_onselchange" });
    }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name listSync
 * @description list Sync 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.listSync = async function() {
    let vMarketTpCd = "";
    if (js_market === "1" || js_market === "2" || js_market === "6") {
        vMarketTpCd = js_market;
    } else {
        vMarketTpCd = rdo_MARKET_TP_CD.getValue();
    }
    url += "?SCREN_ID=" + "ULDSTF21501.xml" + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    url += "&method=listGeneral" + "&outputMessageId=LIST_TREASURYSTOCK_LIST_OUT" + "&service=krx.lds.stf.listingcommon.services.ListingCommonApp" + "&queryId=lds.stf.lstsrch.listSearchTreasury.tabtwo.select.condition" + "&{P}param01=" + edt_SDate.getValue() + // 시작일자
        "&{P}param02=" + edt_EDate.getValue() + // 종료일자
        "&{P}param03=" + txb_ISUR_CD.getValue() + // 법인코드
        "&{P}param04=" + txb_ISUR_CD.getValue() + // 법인코드
        "&{P}param05=" + vMarketTpCd + // 시장구분
        "&{P}param06=" + vMarketTpCd; // 시장구분

    const sbmOptions = {
        id : "sbm_dts_List",
        action : "/listingCommon.do",
        ref : "",
        target : "dts_List=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

};
